// Rate Limiting & Abuse Budgets — models the in-process token buckets (app.py:348 take,
// app.py:393 refund), the long-poll waiter caps (app.py:968 _waiter_slot / its release),
// the bounded identities diagnostic (app.py:362), and the ASGI header-size gate
// (app.py:785 HeaderLimits) that every route sits behind.
module rate_limiting_and_abuse_budgets {
  import basicSpells.* from "./spells/basicSpells"

  // --------------------------------------------------------------------- types & domains

  // (ip, kind) is exactly the key `_buckets` is keyed on in app.py:348-390.
  type BucketKey = (str, str)

  // `cap` is stored per-bucket even though the real code recomputes it from the caller's
  // (per_min, burst) on every call — every real call site always passes the same pair for
  // a given `kind`, so storing the value used at last touch is a faithful, checkable stand-in
  // for "the burst capacity this bucket is actually governed by" (see no_overdraw below).
  type Bucket = { tokens: int, last: int, cap: int }

  // The outcome of the most recent take(), so a single-state invariant can check a
  // per-call fact (app.py:368-372: only the granted branch subtracts a token).
  type LastGrant = { key: BucketKey, granted: bool, tokensBeforeDeduction: int, tokensAfter: int }

  pure val MAX_BUCKETS: int = 3            // app.py:300 MAX_BUCKETS (20_000 in production)
  pure val MAX_HEADERS: int = 48           // app.py:148
  pure val MAX_HEADER_BYTES: int = 8192    // app.py:149
  pure val MAX_WAITERS_TOTAL: int = 3      // app.py:961 (64 in production)
  pure val MAX_WAITERS_PER_IP: int = 2     // app.py:962
  pure val MAX_IDENTITIES: int = 3         // app.py:315 (50_000 in production)

  pure val IPS: Set[str] = Set("ip1", "ip2", "ip3", "ip4")
  pure val KINDS: Set[str] = Set("read", "write", "create")
  // Small representative per-minute rates and bursts — production values (120, 30, and the
  // fractional RATE_ROOMS_PER_DAY/1440) don't matter to the properties below, which are about
  // the *shape* of the refill/cap/eviction rules, not the configured numbers.
  pure val PER_MIN_VALUES: Set[int] = Set(2, 5)
  pure val BURST_VALUES: Set[Option[int]] = Set(None, Some(2), Some(5), Some(8))
  // 0 exercises back-to-back calls with no refill; 50 exercises the min()-clamp once tokens
  // would otherwise overshoot the cap.
  pure val ELAPSED_VALUES: Set[int] = Set(0, 1, 3, 50)
  // Boundary values for HeaderLimits' `> MAX_HEADERS` / `> MAX_HEADER_BYTES` checks
  // (app.py:802): exactly at the cap must pass, one over must reject.
  pure val HEADER_COUNTS: Set[int] = Set(0, 10, 48, 49, 60)
  pure val HEADER_BYTES: Set[int] = Set(0, 4096, 8192, 8193, 10000)

  // ------------------------------------------------------------------------------- state

  var buckets: BucketKey -> Bucket
  var bucketOrder: List[BucketKey]        // OrderedDict iteration order: oldest first
  var lastGrant: LastGrant
  var waitersByIp: str -> int
  var waitersTotal: int
  var now: int                            // abstract monotonic clock (app.py:364 time.monotonic())
  var lastHeaderCheck: { headerCount: int, totalBytes: int, rejected: bool }
  var identities: Set[str]                // app.py:314 _identities

  // --------------------------------------------------------------------------- pure defs

  pure def bucketCap(per_min: int, burstNone: Option[int]): int =
    match burstNone {
      | Some(b) => b
      | None => per_min
    }

  // Fresh bucket starts FULL at cap, exactly like `_buckets.get((ip, kind), (cap, now))`
  // (app.py:366) — a never-seen caller is not pre-penalized.
  pure def getBucket(tbl: BucketKey -> Bucket, key: BucketKey, capV: int, nowV: int): Bucket =
    if (tbl.has(key)) tbl.get(key) else { tokens: capV, last: nowV, cap: capV }

  // Mirrors `tokens + (now - last) * per_min / 60.0`, clamped at cap — `elapsedSinceLast` is
  // this model's stand-in for `(now - last)` already expressed in per_min's own period, so no
  // separate /60 constant is needed (see the `now` comment on `take` for how it's derived).
  pure def refillTokens(tokensBefore: int, per_min: int, elapsedSinceLast: int, capV: int): int =
    min(capV, tokensBefore + elapsedSinceLast * per_min)

  // OrderedDict.move_to_end after get/set (app.py:374): drop any existing occurrence, then
  // append at the tail — the tail is always the most-recently-touched key.
  pure def touchOrder(order: List[BucketKey], key: BucketKey): List[BucketKey] =
    order.select(k => k != key).append(key)

  // `while len(_buckets) > MAX_BUCKETS: popitem(last=False)` (app.py:375-376) — inserting one
  // key at a time only ever needs at most one eviction to get back under the cap.
  pure def evictedOrder(touchedOrder: List[BucketKey]): List[BucketKey] =
    if (touchedOrder.length() > MAX_BUCKETS) touchedOrder.tail() else touchedOrder

  pure def evictedTable(touchedOrder: List[BucketKey], tbl: BucketKey -> Bucket): BucketKey -> Bucket =
    if (touchedOrder.length() > MAX_BUCKETS) tbl.mapRemove(touchedOrder.head()) else tbl

  pure def listToSet(l: List[BucketKey]): Set[BucketKey] =
    l.foldl(Set(), (acc, x) => acc.union(Set(x)))

  // app.py:802 — `len(headers) > MAX_HEADERS or total > MAX_HEADER_BYTES`.
  pure def headerLimitsReject(headerCount: int, totalBytes: int): bool =
    headerCount > MAX_HEADERS or totalBytes > MAX_HEADER_BYTES

  // ----------------------------------------------------------------------------- actions

  action init: bool = all {
    buckets' = Map(),
    bucketOrder' = List(),
    now' = 0,
    lastGrant' = { key: ("", ""), granted: true, tokensBeforeDeduction: 0, tokensAfter: 0 },
    waitersByIp' = Map(),
    waitersTotal' = 0,
    lastHeaderCheck' = { headerCount: 0, totalBytes: 0, rejected: false },
    identities' = Set(),
  }

  // take(request, kind, per_min, burst=None) — mutates in-memory bucket, returns allow/deny
  // (app.py:249/348). `request` resolves to an ip via client_ip(); `elapsed` is this call's
  // pick for how much the abstract clock advances before this bucket is read, so
  // `now' - current.last` plays the role of the real `(now - last)` — a fresh global clock
  // read at every take, exactly as `time.monotonic()` is read fresh on every call.
  action take(ip: str, kind: str, per_min: int, burstNone: Option[int], elapsed: int): bool = {
    val key = (ip, kind)
    val capV = bucketCap(per_min, burstNone)
    val newNow = now + elapsed
    val current = getBucket(buckets, key, capV, newNow)
    val sinceLast = newNow - current.last
    val refilled = refillTokens(current.tokens, per_min, sinceLast, capV)
    val granted = refilled >= 1
    val tokensAfter = if (granted) refilled - 1 else refilled
    val updatedBucket = { tokens: tokensAfter, last: newNow, cap: capV }
    val touchedOrder = touchOrder(bucketOrder, key)
    val insertedTbl = buckets.put(key, updatedBucket)
    all {
      now' = newNow,
      bucketOrder' = evictedOrder(touchedOrder),
      buckets' = evictedTable(touchedOrder, insertedTbl),
      lastGrant' = { key: key, granted: granted, tokensBeforeDeduction: refilled, tokensAfter: tokensAfter },
      waitersByIp' = waitersByIp,
      waitersTotal' = waitersTotal,
      lastHeaderCheck' = lastHeaderCheck,
      identities' = if (identities.size() < MAX_IDENTITIES) identities.union(Set(ip)) else identities,
    }
  }

  // refund(request, kind, per_min, burst=None) — mutates, credits one token back (app.py:294/393).
  // `last` is left exactly as it was on the bucket touched (or "now" for a bucket refund sees
  // first) — refund never reads or advances the clock, matching `last` staying untouched in
  // app.py:401-402.
  action refund(ip: str, kind: str, per_min: int, burstNone: Option[int]): bool = {
    val key = (ip, kind)
    val capV = bucketCap(per_min, burstNone)
    val current = getBucket(buckets, key, capV, now)
    val newTokens = min(capV, current.tokens + 1)
    val updatedBucket = { tokens: newTokens, last: current.last, cap: capV }
    val touchedOrder = touchOrder(bucketOrder, key)
    val insertedTbl = buckets.put(key, updatedBucket)
    all {
      buckets' = evictedTable(touchedOrder, insertedTbl),
      bucketOrder' = evictedOrder(touchedOrder),
      now' = now,
      lastGrant' = lastGrant,
      waitersByIp' = waitersByIp,
      waitersTotal' = waitersTotal,
      lastHeaderCheck' = lastHeaderCheck,
      identities' = identities,
    }
  }

  // _waiter_slot(ip) — mutates long-poll waiter accounting, bounded per-IP and globally
  // (app.py:869/968). The real function is a contextmanager: entering is the acquire modeled
  // here, and the `finally:` release is modeled separately as _waiter_release below, because
  // the two can be arbitrarily far apart in wall-clock time (the caller awaits in between) and
  // can overlap with any other ip's acquire/release — never one atomic step.
  action _waiter_slot(ip: str): bool = {
    val atCapTotal = waitersTotal >= MAX_WAITERS_TOTAL
    val atCapIp = waitersByIp.getOrElse(ip, 0) >= MAX_WAITERS_PER_IP
    val granted = not(atCapTotal) and not(atCapIp)
    all {
      waitersTotal' = if (granted) waitersTotal + 1 else waitersTotal,
      waitersByIp' = if (granted) waitersByIp.put(ip, waitersByIp.getOrElse(ip, 0) + 1) else waitersByIp,
      buckets' = buckets,
      bucketOrder' = bucketOrder,
      now' = now,
      lastGrant' = lastGrant,
      lastHeaderCheck' = lastHeaderCheck,
      identities' = identities,
    }
  }

  // The `finally:` half of the same contextmanager (app.py:982-988) — releases one slot this
  // `ip` currently holds. Guarded on `has(ip)` because a release can only follow a granted
  // acquire; an ip with no held slot (acquire was denied, or every slot already released) has
  // nothing to release.
  action _waiter_release(ip: str): bool = {
    val left = waitersByIp.getOrElse(ip, 0) - 1
    all {
      waitersByIp.has(ip),
      waitersTotal' = waitersTotal - 1,
      waitersByIp' = if (left > 0) waitersByIp.put(ip, left) else waitersByIp.mapRemove(ip),
      buckets' = buckets,
      bucketOrder' = bucketOrder,
      now' = now,
      lastGrant' = lastGrant,
      lastHeaderCheck' = lastHeaderCheck,
      identities' = identities,
    }
  }

  // HeaderLimits (app.py:686/785) — ASGI middleware wrapping the whole app, so this always
  // runs before routing, gates, or any bucket logic reaches `take`/`refund`/`_waiter_slot`.
  // Modeled as its own action (rather than a guard threaded through the other three) because
  // it has no bucket/waiter/identity state of its own to update — `lastHeaderCheck` exists
  // purely so this transition is observable.
  action reject_oversized_headers(headerCount: int, totalBytes: int): bool = all {
    headerLimitsReject(headerCount, totalBytes),
    lastHeaderCheck' = { headerCount: headerCount, totalBytes: totalBytes, rejected: true },
    buckets' = buckets,
    bucketOrder' = bucketOrder,
    now' = now,
    lastGrant' = lastGrant,
    waitersByIp' = waitersByIp,
    waitersTotal' = waitersTotal,
    identities' = identities,
  }

  // Queries (no state transition — modeled as pure defs above, or not modeled at all):
  //   client_ip(request) — query, resolves rate-limit identity from proxy config (app.py:219/318).
  //     Not a separate def: every action above already takes an opaque `ip: str`, which is
  //     exactly client_ip's return type — the identity-spoofing risk it documents is a
  //     deployment-configuration concern, not a violable code invariant (see adversary
  //     dispositions in the handoff).
  //   refill_rate(per_min) — pure query, human-readable refill description (app.py:339/438).
  //   limited(kind, per_min, retry_after) — pure query, builds the 429 body (app.py:354/453).
  //   budget_note(kind, left, per_min) — pure query, builds the warn-before-wall footer (app.py:383/482).
  //     These three only format response text from values the state machine above already
  //     computes (granted/left/wait) — no state read or written, nothing for a property to
  //     check.

  action step: bool = any {
    { nondet ip = IPS.oneOf()
      nondet kind = KINDS.oneOf()
      nondet per_min = PER_MIN_VALUES.oneOf()
      nondet burstNone = BURST_VALUES.oneOf()
      nondet elapsed = ELAPSED_VALUES.oneOf()
      take(ip, kind, per_min, burstNone, elapsed) },
    { nondet ip = IPS.oneOf()
      nondet kind = KINDS.oneOf()
      nondet per_min = PER_MIN_VALUES.oneOf()
      nondet burstNone = BURST_VALUES.oneOf()
      refund(ip, kind, per_min, burstNone) },
    { nondet ip = IPS.oneOf()
      _waiter_slot(ip) },
    { nondet ip = IPS.oneOf()
      _waiter_release(ip) },
    { nondet headerCount = HEADER_COUNTS.oneOf()
      nondet totalBytes = HEADER_BYTES.oneOf()
      reject_oversized_headers(headerCount, totalBytes) },
  }

  // ------------------------------------------------------------------------- invariants

  /// A caller's bucket never holds more tokens than the burst capacity configured for it,
  /// even under arbitrarily interleaved concurrent take()/refund() calls — and therefore a
  /// caller's effective request rate can never exceed the budget the operator configured.
  val no_overdraw: bool =
    buckets.keys().forall(k => buckets.get(k).tokens <= buckets.get(k).cap)

  /// The bucket table never grows past MAX_BUCKETS entries — LRU eviction bounds memory
  /// against a rotating-IP flood, and therefore a distinct-IP flood cannot OOM the process
  /// the way an unbounded table would (app.py:293-299).
  val no_bucket_table_overflow: bool =
    buckets.keys().size() <= MAX_BUCKETS

  /// The LRU order list and the bucket table always name the same set of keys, in step —
  /// eviction and touch can never let the two drift apart (a redundant-representation
  /// consistency check on app.py:373-376's OrderedDict bookkeeping).
  val order_matches_table: bool =
    listToSet(bucketOrder) == buckets.keys() and bucketOrder.length() == buckets.keys().size()

  /// A denied (429) call only ever applies the refill already computed — it never also
  /// subtracts the token that would have been taken had it been granted, and therefore a
  /// caller who is out of budget is never charged twice for the same rejected request.
  val no_phantom_deduction: bool =
    not(lastGrant.granted) implies (lastGrant.tokensAfter == lastGrant.tokensBeforeDeduction)

  /// Long-poll waiter accounting never exceeds either the global or the per-IP cap, and
  /// therefore a caller cannot buy more parked sockets than MAX_WAITERS_TOTAL /
  /// MAX_WAITERS_PER_IP allow — the one gap the design doc (app.py:953-958) names as the
  /// actual attack surface of world-writable long-polling.
  val waiters_bounded: bool =
    waitersTotal <= MAX_WAITERS_TOTAL and
    waitersByIp.keys().forall(ip => waitersByIp.get(ip) <= MAX_WAITERS_PER_IP)

  /// The identities diagnostic set never grows past MAX_IDENTITIES even under a distinct-IP
  /// flood — the same bound app.py:362-363 applies before adding to `_identities`.
  val identities_bounded: bool =
    identities.size() <= MAX_IDENTITIES

  // ------------------------------------------------------------------------ observations

  /// The bucket table is saturated at MAX_BUCKETS — the next new (ip, kind) key can only be
  /// admitted by evicting the oldest entry.
  val bucket_table_full: bool =
    buckets.keys().size() == MAX_BUCKETS

  /// Some caller's bucket is fully drained — their very next call in that (ip, kind) lane
  /// is refused unless enough time has passed to refill at least one token.
  val bucket_drained: bool =
    buckets.keys().exists(k => buckets.get(k).tokens == 0)

  /// The most recent take() was denied — a 429 was returned.
  val request_denied: bool =
    not(lastGrant.granted)

  /// The most recent take() was granted against a real (ip, kind) bucket (excludes init's
  /// placeholder grant).
  val request_granted: bool =
    lastGrant.granted and lastGrant.key != ("", "")

  /// Every long-poll slot is in use — the next _waiter_slot call anywhere is refused.
  val waiters_at_global_cap: bool =
    waitersTotal == MAX_WAITERS_TOTAL

  /// Some IP is holding as many concurrent long-poll slots as it is allowed.
  val waiters_at_per_ip_cap: bool =
    waitersByIp.keys().exists(ip => waitersByIp.get(ip) == MAX_WAITERS_PER_IP)

  /// HeaderLimits rejected an oversized header block before any route ran.
  val oversized_headers_rejected: bool =
    lastHeaderCheck.rejected
}

